use std::{collections::BTreeMap,path::{Path,PathBuf}};
use super::sandbox_contracts::{SandboxError,SandboxPolicy,SandboxTransform};
pub struct PathSandboxInput<'a>{pub surface:&'a str,pub policy:SandboxPolicy,pub platform:&'a str,pub writable_dirs:&'a [PathBuf],pub readonly_dirs:&'a [PathBuf],pub lock_paths:&'a [PathBuf],pub payload_paths:&'a [PathBuf],pub fallback_dir:&'a Path,pub foreign_roots:&'a [PathBuf],pub command:&'a str,pub env:&'a BTreeMap<String,String>,pub session_executable:Option<&'a Path>}
fn identity(warning:Option<String>)->SandboxTransform{SandboxTransform{was_sandboxed:false,warning,executable:None,inner_command:String::new(),profile:None,temp_dir:None,writable_dirs:vec![],readonly_dirs:vec![],writable_files:vec![]}}
fn unavailable(input:&PathSandboxInput<'_>,reason:String)->Result<SandboxTransform,SandboxError>{if input.policy==SandboxPolicy::Required{Err(SandboxError::Unavailable{platform:input.platform.into(),reason})}else{Ok(identity(Some(format!("{} sandbox unavailable on {}: {reason}; running unsandboxed because policy is auto",input.surface,input.platform))))}}
fn canonical(path:&Path)->Result<PathBuf,SandboxError>{path.canonicalize().map_err(SandboxError::Io).map(|p| memory_core::support::paths::strip_verbatim_prefix(&p))}
pub fn build_path_sandbox_transform(input:&PathSandboxInput<'_>,which:&dyn Fn(&str)->Option<String>)->Result<SandboxTransform,SandboxError>{
    if input.policy==SandboxPolicy::Off{return Ok(identity(None));}
    let tool=match input.platform{"darwin"=>"sandbox-exec","linux"=>"bwrap",_=>return unavailable(input,"platform is unsupported".into())};
    let Some(executable)=which(tool)else{return unavailable(input,format!("{tool} not found"));};
    if input.platform!="darwin"&&!input.lock_paths.is_empty()&&input.surface!="facts"{return unavailable(input,format!("{} sandbox cannot grant the agent lockfile paths ({}); bwrap has no minimal grant for entries that do not exist yet",input.platform,input.lock_paths.iter().map(|path|path.to_string_lossy()).collect::<Vec<_>>().join(", ")));}
    let writable_dirs=input.writable_dirs.iter().map(|path|canonical(path)).collect::<Result<Vec<_>,_>>()?;
    let writable_files=input.session_executable.and_then(installed_version_lock).into_iter().collect::<Vec<_>>();
    let (profile,temp_dir)=if input.platform=="darwin"{
        let payloads=input.payload_paths.iter().map(|path|canonical(path)).collect::<Result<Vec<_>,_>>()?;let foreign=input.foreign_roots.iter().map(|path|canonical(path)).collect::<Result<Vec<_>,_>>()?;
        let mut locks=vec![];let mut absent=vec![];for lock in input.lock_paths{let parent=lock.parent().unwrap_or(Path::new("."));if parent.exists(){locks.push(canonical(parent)?.join(lock.file_name().unwrap_or_default()));}else if !absent.contains(&parent){absent.push(parent);}}
        if !absent.is_empty(){return unavailable(input,format!("lock parent directories do not exist ({})",absent.iter().map(|path|path.to_string_lossy()).collect::<Vec<_>>().join(", ")));}
        let fallback;let first=if let Some(first)=payloads.first(){first}else{fallback=canonical(input.fallback_dir)?;&fallback};let temp=first.parent().unwrap_or(Path::new(".")).join(".sandbox-tmp");let mut builder=std::fs::DirBuilder::new();builder.recursive(true);
        #[cfg(unix)]{use std::os::unix::fs::DirBuilderExt;builder.mode(0o700);}
        builder.create(&temp).map_err(SandboxError::Io)?;
        let quote=|path:&Path|serde_json::Value::String(path.to_string_lossy().into_owned()).to_string();let mut lines=vec!["(version 1)".into(),"(allow default)".into(),"(deny file-write*)".into()];for path in writable_dirs.iter().chain(std::iter::once(&temp)){lines.push(format!("(allow file-write* (subpath {}))",quote(path)));}for path in locks{lines.push(format!("(allow file-write* (literal {}) (subpath {}))",quote(&path),quote(&path)));}for path in &writable_files{lines.push(format!("(allow file-write* (literal {}))",quote(path)));}lines.extend(["(allow file-write* (literal \"/dev/null\"))".into(),"(allow file-write* (literal \"/dev/tty\"))".into()]);for path in payloads{lines.push(format!("(allow file-read* (literal {}))",quote(&path)));}for path in foreign{lines.push(format!("(deny file-read* (subpath {}))",quote(&path)));}(Some(lines.join("\n")),Some(temp))
    }else{(None,None)};
    let inner=if Path::new(input.command).is_absolute()||input.command.starts_with('/'){Some(input.command.into())}else{input.env.get("PATH").and_then(|path|std::env::split_paths(path).filter(|entry|!entry.as_os_str().is_empty()).map(|entry|entry.join(input.command)).find(|path|is_executable(path))).map(|path|path.to_string_lossy().into_owned())};
    let Some(inner_command)=inner else{return Ok(identity(Some(format!("{} sandbox unavailable: inner command \"{}\" is not absolute and could not be resolved; running unsandboxed",input.surface,input.command))));};
    let readonly_dirs=if input.surface=="facts"&&input.platform=="linux"{input.readonly_dirs.iter().map(|path|canonical(path)).collect::<Result<Vec<_>,_>>()?}else{vec![]};
    Ok(SandboxTransform{was_sandboxed:true,warning:None,executable:Some(executable),inner_command,profile,temp_dir,writable_dirs,readonly_dirs,writable_files})
}
fn is_version_name(version:&str)->bool{!version.is_empty()&&version.len()<=128&&!version.starts_with('.')&&version.chars().all(|c|c.is_ascii_alphanumeric()||matches!(c,'.'|'_'|'+'|'-'))}
/// Shared session lock for a versioned install, `R/versions/<v>.lock`, opened by `session_lease`.
/// `None` for a dev or flat binary, or when the lock file does not exist yet. bwrap cannot bind a missing path.
fn installed_version_lock(executable:&Path)->Option<PathBuf>{
    let executable=std::fs::canonicalize(executable).ok()?;
    let version_dir=executable.parent()?;
    let versions=version_dir.parent()?;
    let root=versions.parent()?;
    let version=version_dir.file_name()?.to_str()?;
    if versions.file_name().is_none_or(|name|name!="versions")||!is_version_name(version)||!root.join("current.json").is_file(){return None;}
    let lock=versions.join(format!("{version}.lock"));
    lock.is_file().then_some(lock)
}
fn is_executable(path:&Path)->bool{
    #[cfg(unix)]{use std::os::unix::fs::PermissionsExt;std::fs::metadata(path).is_ok_and(|metadata|metadata.permissions().mode()&0o111!=0)}
    #[cfg(not(unix))]{path.exists()}
}
#[cfg(test)]mod tests{
    use super::*;use crate::sandbox_contracts::SandboxSpawnArgs;
    fn input<'a>(root:&'a Path,env:&'a BTreeMap<String,String>)->PathSandboxInput<'a>{PathSandboxInput{surface:"reflection",policy:SandboxPolicy::Required,platform:"linux",writable_dirs:&[],readonly_dirs:&[],lock_paths:&[],payload_paths:&[],fallback_dir:root,foreign_roots:&[],command:"/bin/sh",env,session_executable:None}}
    #[test]fn off_skips_detection(){let root=tempfile::tempdir().unwrap();let env=BTreeMap::new();let mut input=input(root.path(),&env);input.policy=SandboxPolicy::Off;let transform=build_path_sandbox_transform(&input,&|_|panic!("must not detect")).unwrap();assert!(!transform.was_sandboxed);assert!(transform.warning.is_none());}
    #[test]fn linux_wraps_command_and_preserves_environment(){let root=tempfile::tempdir().unwrap();let env=BTreeMap::new();let dirs=vec![root.path().to_owned()];let mut input=input(root.path(),&env);input.writable_dirs=&dirs;let transform=build_path_sandbox_transform(&input,&|_|Some("/usr/bin/bwrap".into())).unwrap();let original=SandboxSpawnArgs{command:"/bin/sh".into(),args:vec!["-c".into(),"exit 0".into()],cwd:root.path().into(),env:env.clone()};let result=transform.apply(original);assert!(transform.was_sandboxed);assert_eq!(result.command,"/usr/bin/bwrap");assert_eq!(&result.args[result.args.len()-4..],["--","/bin/sh","-c","exit 0"]);assert_eq!(result.env,env);assert!(result.args.contains(&"--bind".into()));}
    #[test]fn required_and_auto_missing_or_unsupported(){let root=tempfile::tempdir().unwrap();let env=BTreeMap::new();let mut input=input(root.path(),&env);assert!(matches!(build_path_sandbox_transform(&input,&|_|None),Err(SandboxError::Unavailable{..})));input.policy=SandboxPolicy::Auto;assert!(!build_path_sandbox_transform(&input,&|_|None).unwrap().was_sandboxed);input.platform="win32";assert!(build_path_sandbox_transform(&input,&|_|panic!("must not detect")).unwrap().warning.unwrap().contains("unsupported"));}
    #[test]fn unresolved_inner_degrades_even_required(){let root=tempfile::tempdir().unwrap();let env=BTreeMap::new();let mut input=input(root.path(),&env);input.command="missing";let transform=build_path_sandbox_transform(&input,&|_|Some("bwrap".into())).unwrap();assert!(!transform.was_sandboxed);assert!(transform.warning.unwrap().contains("could not be resolved"));}
    #[test]fn darwin_grants_only_absent_lock_entries(){let root=tempfile::tempdir().unwrap();let canonical_root=memory_core::support::paths::strip_verbatim_prefix(&root.path().canonicalize().unwrap());let env=BTreeMap::new();let locks=vec![root.path().join("settings.json.lock")];let payloads=vec![root.path().join("payload.json")];std::fs::write(&payloads[0],"{}").unwrap();let mut input=input(root.path(),&env);input.platform="darwin";input.lock_paths=&locks;input.payload_paths=&payloads;let transform=build_path_sandbox_transform(&input,&|_|Some("sandbox-exec".into())).unwrap();let profile=transform.profile.unwrap();assert!(profile.contains("settings.json.lock"));assert!(!profile.contains("(allow file-write* (subpath /"));assert_eq!(transform.temp_dir.unwrap(),canonical_root.join(".sandbox-tmp"));}
    #[test]fn linux_facts_accepts_brokered_host_lock_paths(){let root=tempfile::tempdir().unwrap();let env=BTreeMap::new();let locks=vec![root.path().join("settings.json.lock"),root.path().join("auth.json.lock")];let readonly=vec![root.path().join("lock-broker")];std::fs::create_dir(&readonly[0]).unwrap();let mut input=input(root.path(),&env);input.surface="facts";input.lock_paths=&locks;input.readonly_dirs=&readonly;let transform=build_path_sandbox_transform(&input,&|_|Some("bwrap".into())).unwrap();assert!(transform.was_sandboxed);let canonical_readonly=readonly.iter().map(|path|memory_core::support::paths::strip_verbatim_prefix(&path.canonicalize().unwrap())).collect::<Vec<_>>();assert_eq!(transform.readonly_dirs,canonical_readonly);}
    #[test]fn linux_reflection_still_refuses_host_lock_paths(){let root=tempfile::tempdir().unwrap();let env=BTreeMap::new();let locks=vec![root.path().join("settings.json.lock")];let mut input=input(root.path(),&env);input.lock_paths=&locks;assert!(matches!(build_path_sandbox_transform(&input,&|_|Some("bwrap".into())),Err(SandboxError::Unavailable{..})));}
    fn versioned_payload(root:&Path,version:&str)->PathBuf{let dir=root.join("versions").join(version);std::fs::create_dir_all(&dir).unwrap();let executable=dir.join("mhc");std::fs::write(&executable,b"").unwrap();std::fs::write(root.join("current.json"),b"{}").unwrap();executable}
    #[test]fn version_lock_matches_the_running_payload_only(){let root=tempfile::tempdir().unwrap();let executable=versioned_payload(root.path(),"2026.10.21.1");assert!(installed_version_lock(&executable).is_none());let lock=root.path().join("versions/2026.10.21.1.lock");std::fs::write(&lock,b"").unwrap();assert_eq!(installed_version_lock(&executable).unwrap(),lock.canonicalize().unwrap());let spaced=versioned_payload(root.path(),"bad version");std::fs::write(root.path().join("versions/bad version.lock"),b"").unwrap();assert!(installed_version_lock(&spaced).is_none());assert!(installed_version_lock(&root.path().join("current.json")).is_none());}
    #[test]fn sandboxed_child_can_open_only_the_version_lock_file(){let root=tempfile::tempdir().unwrap();let executable=versioned_payload(root.path(),"2026.10.21.1");let lock=root.path().join("versions/2026.10.21.1.lock");std::fs::write(&lock,b"").unwrap();let lock=installed_version_lock(&executable).unwrap();let env=BTreeMap::new();let versions=lock.parent().unwrap().to_path_buf();
        for surface in ["reflection","facts"]{let mut input=input(root.path(),&env);input.surface=surface;input.session_executable=Some(&executable);let transform=build_path_sandbox_transform(&input,&|_|Some("bwrap".into())).unwrap();let args=transform.apply(SandboxSpawnArgs{command:"/bin/sh".into(),args:vec![],cwd:root.path().into(),env:env.clone()});let lock_s=lock.to_string_lossy().into_owned();let versions_s=versions.to_string_lossy().into_owned();assert!(args.args.windows(3).any(|window|window==["--bind",lock_s.as_str(),lock_s.as_str()]),"{surface}");assert!(!args.args.windows(3).any(|window|window[0]=="--bind"&&window[1]==versions_s),"{surface}");}
        let mut darwin=input(root.path(),&env);darwin.platform="darwin";darwin.session_executable=Some(&executable);let profile=build_path_sandbox_transform(&darwin,&|_|Some("sandbox-exec".into())).unwrap().profile.unwrap();let quoted=serde_json::Value::String(lock.to_string_lossy().into_owned()).to_string();assert!(profile.contains(&format!("(allow file-write* (literal {quoted}))")),"{profile}");let versions_quoted=serde_json::Value::String(versions.to_string_lossy().into_owned()).to_string();assert!(!profile.contains(&format!("(allow file-write* (subpath {versions_quoted}))")),"{profile}");}
}
